/**
 * Real content set (production and dev builds). Resolved through the `@content-data` alias
 * when the Vite mode is not `e2e` (Architecture §3). The JSON is generated by
 * `npm run content:build` — never edit it by hand. Validation happens in `./index.ts`.
 */
import type { RawContentSet } from './schema';
import stations from './data/stations.json';
import tour from './data/tour.json';

const peopleModules: Record<string, unknown> = import.meta.glob('./data/people/*.json', {
  eager: true,
  import: 'default',
});

export const raw: RawContentSet = {
  tour,
  stations,
  people: Object.keys(peopleModules)
    .sort()
    .map((file) => peopleModules[file]),
};
